package net.civeira.phylax.features.access.trustedclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class TokenEndpointAuthSigningAlgVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property token endpoint auth signing alg of trusted client ")
  void test_token_endpoint_auth_signing_alg_v_o_builder() {
    Assertions.assertFalse(
        TokenEndpointAuthSigningAlgVO.nullValue().getTokenEndpointAuthSigningAlg().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(
        TokenEndpointAuthSigningAlgVO.tryFrom(null).getTokenEndpointAuthSigningAlg().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one",
        TokenEndpointAuthSigningAlgVO.from("one").getTokenEndpointAuthSigningAlg().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> TokenEndpointAuthSigningAlgVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]",
        TokenEndpointAuthSigningAlgVO.from("one").toString());
  }
}
